record.field:

if record.x_studio_mktcode:
    equipo_venta = model.env['crm.team'].search([('x_studio_cdigo', '=', record.x_studio_mktcode)],
    limit=1)
    if equipo_venta:
        record['team_id'] = equipo_venta.id
    else: record['team_id'] = 1


if record.team_id:
        if record.x_studio_tipo_de_venta == 'Full':
                record['warehouse_id'] = record.team_id.x_studio_almacn_full.id
                #record['x_studio_almacen'] = record.team_id.x_studio_almacn_full.id
        elif record.x_studio_tipo_de_venta == 'Drop':
                record['warehouse_id'] = record.team_id.x_studio_almacn_drop.id
                #record['x_studio_almacen'] = record.team_id.x_studio_almacn_drop.id
else:
    record['warehouse_id'] = 1


# Acción Automatizada para calcular margen en sale.order
# Activador: Al crear y actualizar
# Modelo: sale.order

# ========== CONFIGURACIÓN DE RANGOS ==========
RANGO_EXCELENTE = 15    # >= % - Verde
RANGO_BUENO = 5        # >= % - Amarillo
RANGO_REGULAR = 0       # >= % - Naranja
# < 0% - Rojo (pérdida)

# Configuración de colores y iconos
COLORES = {
    'excelente': {'fondo': '#d4edda', 'texto': '#155724', 'icono': '🟢'},
    'bueno': {'fondo': '#fff3cd', 'texto': '#856404', 'icono': '🟡'},
    'regular': {'fondo': '#ffeaa7', 'texto': '#d35400', 'icono': '🟠'},
    'malo': {'fondo': '#f8d7da', 'texto': '#721c24', 'icono': '🔴'}
}
# ============================================

for record in records:
    # Total de venta (con impuestos incluidos)
    total_venta = record.amount_total

    # Calcular costos totales
    total_costo_productos = 0
    total_envios_comisiones = 0

    # Sumar costos de productos con IVA
    for line in record.order_line:
        # Aplicar IVA al costo (ajustar porcentaje según corresponda)
        costo_con_iva = line.product_id.standard_price * line.product_uom_qty
        total_costo_productos += costo_con_iva

    # Sumar envíos y comisiones
    for envcom_line in record.x_studio_lineenvcom:
        total_envios_comisiones += envcom_line.x_studio_subtotal

    # Calcular ganancia y margen
    ganancia = total_venta - total_costo_productos - total_envios_comisiones
    margen_porcentaje = (ganancia / total_venta * 100) if total_venta > 0 else 0

    # Determinar categoría según rangos
    if margen_porcentaje >= RANGO_EXCELENTE:
        categoria = 'excelente'
    elif margen_porcentaje >= RANGO_BUENO:
        categoria = 'bueno'
    elif margen_porcentaje >= RANGO_REGULAR:
        categoria = 'regular'
    else:
        categoria = 'malo'

    # Obtener colores e icono
    config_color = COLORES[categoria]

    # Generar HTML del margen
    html_margen = f"""
    <div style="
        background: {config_color['fondo']};
        color: {config_color['texto']};
        padding: 4px 8px;
        border-radius: 6px;
        font-weight: 600;
        text-align: center;
        border: 1px solid {config_color['texto']}20;
        font-size: 12px;
        display: inline-flex;
        align-items: center;
        gap: 4px;
        white-space: nowrap;
    ">
        <span>{config_color['icono']}</span>
        <span>${ganancia:,.0f}</span>
        <span style="font-size: 10px; opacity: 0.8;">({margen_porcentaje:+.0f}%)</span>
    </div>
    """

    # Asignar al campo
    record['x_studio_analisis_de_margen'] = html_margen
